16	// render.go is the line-oriented half of this package. The dashboard above it
17	// (tui.go) owns a full-screen bubbletea program; the commands people actually
18	// run — `setup`, `status` — write ordinary lines to a stream that may be a
19	// terminal, a pipe, a CI log, a systemd journal or a hook whose stdout is
20	// contractually empty. They still deserve colour, marks, spinners and bars when
21	// the destination can render them, and byte-stable plain text when it cannot.
22	//
23	// Both halves share one palette (Theme), so a component that is Good-coloured in
24	// the dashboard is the same colour on a setup line. What they do NOT share is
25	// lipgloss's implicit renderer: lipgloss decides colour from a package-global
26	// profile bound to os.Stdout, which makes styled output untestable (it depends
27	// on how the TEST process was started) and wrong for a command writing to
28	// stderr. Caps below is an explicit, injectable answer to "what can THIS stream
29	// render", and every escape sequence in this file is gated on it.
30	
31	// Caps is what a destination stream can render.
32	type Caps struct {
33		// TTY reports whether the stream is a terminal. It gates every in-place
34		// repaint: a pipe gets whole lines and nothing else.
35		TTY bool
36		// Color reports whether ANSI colour may be emitted. TTY implies nothing —
37		// NO_COLOR, TERM=dumb and a non-terminal each turn it off independently.
38		Color bool
39		// Unicode reports whether non-ASCII glyphs will render. A terminal whose
40		// locale is not UTF-8 draws them as replacement boxes, which is where the
41		// stray "□" in the spinner and the em dashes came from.
42		Unicode bool
43		// Width is the usable line width; 0 means unknown (do not truncate).
44		Width int
45	}
46	
47	// PlainCaps is the byte-stable mode: whole lines, ASCII, no colour. Every
48	// non-terminal destination resolves to exactly this, which is what makes the
49	// plain path safe to assert on in tests and safe to pipe into a log.
50	func PlainCaps() Caps { return Caps{} }
51	
52	// EnvLookup is os.LookupEnv's shape. The "found" half matters: NO_COLOR is
53	// honoured by PRESENCE, so NO_COLOR= (empty) must still disable colour, and a
54	// plain getenv cannot tell that from unset.
55	type EnvLookup func(string) (string, bool)
56	
57	// DetectCaps resolves the capabilities of w from the process environment.
58	func DetectCaps(w io.Writer) Caps { return DetectCapsWithEnv(w, os.LookupEnv) }
59	
60	// DetectCapsWithEnv is DetectCaps with the environment injected, so the
61	// TTY/NO_COLOR/locale matrix is testable without mutating process state.
62	func DetectCapsWithEnv(w io.Writer, lookup EnvLookup) Caps {
63		file, ok := w.(*os.File)
64		if !ok || file == nil {
65			return PlainCaps()
66		}
67		fd := file.Fd()
68		if !isatty.IsTerminal(fd) && !isatty.IsCygwinTerminal(fd) {
69			return PlainCaps()
70		}
71		caps := terminalCaps(lookup)
72		if caps.TTY {
73			caps.Width = terminalWidth(fd, func(key string) string { value, _ := lookup(key); return value })
74		}
75		return caps
76	}
77	
78	// terminalCaps resolves environment policy after the caller verifies a terminal.
79	func terminalCaps(lookup EnvLookup) Caps {
80		if lookup == nil {
81			lookup = func(string) (string, bool) { return "", false }
82		}
83		getenv := func(key string) string { value, _ := lookup(key); return value }
84		if !SupportsFullScreen(getenv) {
85			return PlainCaps()
86		}
87		caps := Caps{TTY: true, Unicode: localeIsUTF8(getenv)}
88		// NO_COLOR is defined by presence, including an empty value.
89		if _, noColor := lookup("NO_COLOR"); !noColor {
90			caps.Color = true
91		}
92		return caps
93	}
94	
95	// SupportsFullScreen reports whether TERM describes a terminal that can be
96	// driven with escape sequences at all. TERM=dumb and an unset TERM do not: a
97	// dumb terminal has no cursor addressing, no alternate screen and no SGR, so
98	// anything written for one arrives as literal escape bytes.
99	//
100	// It gates both halves of this package. The line renderer above drops to
101	// PlainCaps; the dashboard declines to start and the caller prints the plain
102	// summary instead — otherwise `dash` on TERM=dumb pushed \x1b[?1049h, a
103	// rounded-border layout and 256-colour SGR at a terminal that renders every
104	// byte of it as text.
105	func SupportsFullScreen(getenv func(string) string) bool {
106		if getenv == nil {
107			return false
108		}
109		term := strings.TrimSpace(getenv("TERM"))
110		return term != "" && term != "dumb"
111	}
112	
113	// terminalWidth resolves the usable line width for a terminal, in order of
114	// authority: the kernel, then COLUMNS, then a conservative 80.
115	//
116	// The fallback is not optional. On a terminal of UNKNOWN width the in-place
117	// line is not truncated, so a long label wraps — and the carriage-return erase
118	// only ever clears the last physical row, leaving the wrapped remainder on
119	// screen under the final line. That is precisely the "every phase prints twice"
120	// report. Guessing 80 can clip a label on a wide terminal; not guessing
121	// reintroduces the bug.
122	func terminalWidth(fd uintptr, getenv func(string) string) int {
123		if width, _, err := xterm.GetSize(fd); err == nil && width > 0 {
124			return width
125		}
126		if columns := strings.TrimSpace(getenv("COLUMNS")); columns != "" {
127			width := 0
128			for _, ch := range columns {
129				if ch < '0' || ch > '9' {
130					width = 0
131					break
132				}
133				width = width*10 + int(ch-'0')
134			}
135			if width > 0 {
136				return width
137			}
138		}
139		return 80
140	}
