142	// localeIsUTF8 reports whether the locale promises UTF-8 output. The check is
143	// deliberately conservative: an unset or non-UTF-8 locale falls back to ASCII
144	// glyphs rather than gambling that the font has a spinner in it.
145	func localeIsUTF8(getenv func(string) string) bool {
146		for _, key := range []string{"LC_ALL", "LC_CTYPE", "LANG"} {
147			value := strings.TrimSpace(getenv(key))
148			if value == "" {
149				continue
150			}
151			lowered := strings.ToLower(value)
152			return strings.Contains(lowered, "utf-8") || strings.Contains(lowered, "utf8")
153		}
154		// Windows Terminal and the VS Code terminal are UTF-8 without ever setting
155		// a POSIX locale.
156		return strings.TrimSpace(getenv("WT_SESSION")) != "" ||
157			strings.EqualFold(strings.TrimSpace(getenv("TERM_PROGRAM")), "vscode")
158	}
