160	// Mark is a per-outcome status glyph.
161	type Mark int
162	
163	const (
164		// MarkDone is a component that built.
165		MarkDone Mark = iota
166		// MarkFailed is a component that was attempted and blew up.
167		MarkFailed
168		// MarkSkipped is a component that was deliberately not attempted.
169		MarkSkipped
170		// MarkPending is a component that has not reported yet.
171		MarkPending
