174	// Renderer turns semantic pieces (a mark, a bar, a phase colour) into bytes
175	// appropriate for one destination stream.
176	type Renderer struct {
177		theme Theme
178		caps  Caps
179	}
180	
181	// NewRenderer builds a renderer for w, detecting what w can render.
182	func NewRenderer(w io.Writer) *Renderer {
183		theme, _ := ThemeByName(os.Getenv("ENTIRE_BRAIN_THEME"))
184		return &Renderer{theme: theme, caps: DetectCaps(w)}
185	}
186	
187	// NewRendererWith builds a renderer with an explicit theme and capabilities.
188	func NewRendererWith(theme Theme, caps Caps) *Renderer {
189		return &Renderer{theme: theme, caps: caps}
190	}
191	
192	// Caps reports what this renderer's destination can render.
193	func (r *Renderer) Caps() Caps {
194		if r == nil {
195			return PlainCaps()
196		}
197		return r.caps
198	}
199	
200	// Theme reports the palette in use.
201	func (r *Renderer) Theme() Theme {
202		if r == nil {
203			return themes["default"]
204		}
205		return r.theme
206	}
