208	// Paint wraps s in the SGR sequence for c, or returns s untouched when colour
209	// is off. It emits the escape itself rather than delegating to lipgloss because
210	// lipgloss resolves colour from a process-global profile bound to os.Stdout —
211	// which is neither the stream we are writing to nor stable under `go test`.
212	func (r *Renderer) Paint(c lipgloss.Color, s string) string {
213		if r == nil || !r.caps.Color || s == "" {
214			return s
215		}
216		seq := ansiForeground(c)
217		if seq == "" {
218			return s
219		}
220		return seq + s + "\x1b[0m"
221	}
222	
223	// Bold renders s bold when the stream supports styling.
224	func (r *Renderer) Bold(s string) string {
225		if r == nil || !r.caps.Color || s == "" {
226			return s
227		}
228		return "\x1b[1m" + s + "\x1b[0m"
229	}
230	
231	// Dim renders s in the muted palette colour.
232	func (r *Renderer) Dim(s string) string { return r.Paint(r.Theme().Dim, s) }
233	
234	// spinnerFramesUnicode is the braille spinner; spinnerFramesASCII is the
235	// fallback for a terminal whose locale cannot promise UTF-8. The ASCII set is
236	// the classic four-frame bar, which is what the "-\|/" contract in the CLI
237	// expects.
238	var (
239		spinnerFramesUnicode = []string{"⠋", "⠙", "⠹", "⠸", "⠼", "⠴", "⠦", "⠧", "⠇", "⠏"}
240		spinnerFramesASCII   = []string{"-", "\\", "|", "/"}
241	)
242	
243	// Spinner returns the frame for tick. It is pure: the caller owns the clock,
244	// so a test can assert frame N without sleeping.
245	func (r *Renderer) Spinner(tick int) string {
246		frames := spinnerFramesASCII
247		if r != nil && r.caps.Unicode {
248			frames = spinnerFramesUnicode
249		}
250		if tick < 0 {
251			tick = -tick
252		}
253		return frames[tick%len(frames)]
254	}
255	
256	// SpinnerFrames reports the glyph set in use, for tests and for callers that
257	// need to size a column.
258	func (r *Renderer) SpinnerFrames() []string {
259		if r != nil && r.caps.Unicode {
260			return append([]string(nil), spinnerFramesUnicode...)
261		}
262		return append([]string(nil), spinnerFramesASCII...)
263	}
