265	// Mark renders an outcome glyph, coloured by outcome.
266	func (r *Renderer) Mark(m Mark) string {
267		glyph, color := r.markGlyph(m)
268		return r.Paint(color, glyph)
269	}
270	
271	// MarkGlyph is the outcome glyph WITHOUT colour, for callers that have to
272	// budget a line's width before painting it. Measuring the painted form would
273	// charge the SGR bytes as display width and shrink the line for no reason —
274	// the same reason liveLine measures the plain spinner frame rather than the
275	// coloured one.
276	func (r *Renderer) MarkGlyph(m Mark) string {
277		glyph, _ := r.markGlyph(m)
278		return glyph
279	}
