281	func (r *Renderer) markGlyph(m Mark) (string, lipgloss.Color) {
282		theme := r.Theme()
283		unicode := r != nil && r.caps.Unicode
284		switch m {
285		case MarkDone:
286			if unicode {
287				return "✓", theme.Good
288			}
289			return "+", theme.Good
290		case MarkFailed:
291			if unicode {
292				return "✗", theme.Bad
293			}
294			return "x", theme.Bad
295		case MarkSkipped:
296			if unicode {
297				return "−", theme.Dim
298			}
299			return "-", theme.Dim
300		default:
301			if unicode {
302				return "·", theme.Dim
303			}
304			return ".", theme.Dim
305		}
306	}
