308	// Dash is an em dash where the locale can draw one and a plain hyphen where it
309	// cannot. The stray "□" people saw mid-line was an em dash in a terminal whose
310	// locale was not UTF-8.
311	func (r *Renderer) Dash() string {
312		if r != nil && r.caps.Unicode {
313			return "—"
314		}
315		return "--"
316	}
317	
318	// Bullet is the mid-dot separator where the locale can draw one and a pipe
319	// where it cannot. Same reasoning as Dash: a hard-coded "\u00b7" renders as a
320	// replacement box on a terminal whose locale is not UTF-8.
321	func (r *Renderer) Bullet() string {
322		if r != nil && r.caps.Unicode {
323			return "\u00b7"
324		}
325		return "|"
326	}
