389	// Truncate clips s to the renderer's line width, measured in display cells so a
390	// CJK or emoji-bearing label is not cut mid-glyph. A live line that WRAPS is
391	// the reason phase lines looked doubled: the carriage-return rewrite only ever
392	// clears the last physical row, so the wrapped first row stays on screen and
393	// the final line prints under it.
394	func (r *Renderer) Truncate(s string) string {
395		if r == nil || r.caps.Width <= 0 {
396			return s
397		}
398		// One cell of slack: writing into the last column makes some terminals wrap
399		// eagerly, which is the very thing being avoided.
400		return r.TruncateTo(s, r.caps.Width-1)
401	}
402	
403	// TruncateTo clips s to limit display cells. It must be given PLAIN text: the
404	// measurement counts runes, so an already-coloured string would have its escape
405	// bytes charged as width. Callers that colour a line build it as plain text,
406	// truncate here, and colour the pieces afterwards.
407	func (r *Renderer) TruncateTo(s string, limit int) string {
408		if limit <= 0 {
409			return ""
410		}
411		tail := "..."
412		if r != nil && r.caps.Unicode {
413			tail = "…"
414		}
415		if limit <= 1 {
416			tail = ""
417		} else if runewidth.StringWidth(tail) > limit {
418			tail = ""
419		}
420		return truncateANSI(s, limit, tail)
421	}
422	
423	// truncateANSI truncates to a VISIBLE cell count, never cutting inside an
424	// escape sequence, and closes a colour the cut would have left open.
425	//
426	// runewidth counts an escape's bytes as cells and will happily cut through the
427	// middle of one. Both are wrong on a string that is already painted, and the
428	// second is the worse of the two: a terminal handed `ESC [ 3` with no final
429	// byte waits for the rest of the sequence and swallows whatever follows it.
430	// Observed live on setup's progress bar, which composes a per-cell coloured
431	// bar and hands it on as a label for this function to budget:
432	//
433	//	ESC[38;5;203m█ESC[0m ... ESC[3…ESC[0m
434	//	                          ^^^^^ cut mid-sequence, terminal eats the rest
435	func truncateANSI(s string, limit int, tail string) string {
436		if limit <= 0 {
437			return ""
438		}
439		if ansiVisibleWidth(s) <= limit {
440			return s
441		}
442		budget := limit - runewidth.StringWidth(tail)
443		if budget < 0 {
444			budget = 0
445		}
446		var b strings.Builder
447		width, open := 0, false
448		for i := 0; i < len(s); {
449			if s[i] == 0x1b {
450				// Copy the whole sequence or none of it; never a prefix.
451				j := skipANSI(s, i)
452				seq := s[i:j]
453				b.WriteString(seq)
454				// Track whether a colour is left open, so the cut can close it.
455				if strings.HasSuffix(seq, "m") {
456					open = seq != "\x1b[0m" && seq != "\x1b[m"
457				}
458				i = j
459				continue
460			}
461			rn, size := utf8.DecodeRuneInString(s[i:])
462			w := runewidth.RuneWidth(rn)
463			if width+w > budget {
464				break
465			}
466			b.WriteString(s[i : i+size])
467			width += w
468			i += size
469		}
470		b.WriteString(tail)
471		if open {
472			b.WriteString("\x1b[0m")
473		}
474		return b.String()
475	}
476	
477	// ansiVisibleWidth is StringWidth with escape sequences charged nothing.
478	func ansiVisibleWidth(s string) int {
479		width := 0
480		for i := 0; i < len(s); {
481			if s[i] == 0x1b {
482				i = skipANSI(s, i)
483				continue
484			}
485			rn, size := utf8.DecodeRuneInString(s[i:])
486			width += runewidth.RuneWidth(rn)
487			i += size
488		}
489		return width
490	}
491	
492	// skipANSI returns the index just past the escape sequence starting at i.
493	//
494	// The shape is ESC '[' <params 0x30-0x3f> <intermediates 0x20-0x2f> <final
495	// 0x40-0x7e>. The '[' must be stepped over BEFORE hunting the final byte:
496	// 0x5b is itself inside the final-byte range, so a scanner that does not
497	// will stop on the bracket and read the parameters as visible text. That is
498	// not hypothetical — it is the bug the first draft of this function shipped,
499	// which measured "\x1b[38;5;45m" as eight visible cells.
500	func skipANSI(s string, i int) int {
501		j := i + 1
502		if j < len(s) && s[j] == '[' {
503			j++
504			for j < len(s) && s[j] >= 0x30 && s[j] <= 0x3f {
505				j++
506			}
507			for j < len(s) && s[j] >= 0x20 && s[j] <= 0x2f {
508				j++
509			}
510		}
511		if j < len(s) && isANSIFinalByte(s[j]) {
512			j++
513		}
514		return j
515	}
516	
517	// isANSIFinalByte reports the byte that ends a CSI sequence (@ through ~).
518	func isANSIFinalByte(b byte) bool { return b >= 0x40 && b <= 0x7e }
519	
520	// Width reports the usable line width, 0 when unknown.
521	func (r *Renderer) Width() int {
522		if r == nil {
523			return 0
524		}
525		return r.caps.Width
526	}
