528	// Phase names the stage of onboarding a line belongs to. Colour-coding by phase
529	// is what makes a scrolling setup readable at a glance: the instant core, the
530	// background backfill and the daemon are three different kinds of work with
531	// three different cost profiles, and a reader should not have to parse the text
532	// to tell which one a line came from.
533	type Phase int
534	
535	const (
536		// PhaseNeutral is an uncategorised line.
537		PhaseNeutral Phase = iota
538		// PhaseInstant is the free, blocking, deterministic core.
539		PhaseInstant
540		// PhaseBackfill is the detached, token-spending fact backfill.
541		PhaseBackfill
542		// PhaseDaemon is workspace registration and the background watcher.
543		PhaseDaemon
544		// PhaseDone marks a completed step.
545		PhaseDone
546		// PhaseSkipped marks a step that was deliberately not run.
547		PhaseSkipped
548		// PhaseFailed marks a step that was attempted and failed.
549		PhaseFailed
550	)
551	
552	// PhaseColor resolves the palette entry for a phase.
553	func (r *Renderer) PhaseColor(p Phase) lipgloss.Color {
554		theme := r.Theme()
555		switch p {
556		case PhaseInstant:
557			return theme.Link
558		case PhaseBackfill:
559			return theme.Alt
560		case PhaseDaemon:
561			return theme.Accent
562		case PhaseDone:
563			return theme.Good
564		case PhaseSkipped:
565			return theme.Flag
566		case PhaseFailed:
567			return theme.Bad
568		default:
569			return theme.Text
570		}
571	}
572	
573	// PhasePaint colours s for a phase.
574	func (r *Renderer) PhasePaint(p Phase, s string) string {
575		if p == PhaseNeutral {
576			return s
577		}
578		return r.Paint(r.PhaseColor(p), s)
579	}
580	
581	// ansiForeground converts a palette colour into an SGR foreground sequence.
582	// lipgloss.Color carries either an xterm-256 index ("214") or a hex triplet
583	// ("#f9e2af"); both themes in this package use both forms.
584	func ansiForeground(c lipgloss.Color) string {
585		value := strings.TrimSpace(string(c))
586		if value == "" {
587			return ""
588		}
589		if strings.HasPrefix(value, "#") {
590			r, g, b, ok := parseHexColor(value)
591			if !ok {
592				return ""
593			}
594			return fmt.Sprintf("\x1b[38;2;%d;%d;%dm", r, g, b)
595		}
596		index := 0
597		for _, ch := range value {
598			if ch < '0' || ch > '9' {
599				return ""
600			}
601			index = index*10 + int(ch-'0')
602			if index > 255 {
603				return ""
604			}
605		}
606		return fmt.Sprintf("\x1b[38;5;%dm", index)
607	}
608	
609	func parseHexColor(value string) (int, int, int, bool) {
610		digits := value[1:]
611		if len(digits) == 3 {
612			expanded := make([]byte, 0, 6)
613			for i := 0; i < 3; i++ {
614				expanded = append(expanded, digits[i], digits[i])
615			}
616			digits = string(expanded)
617		}
618		if len(digits) != 6 {
619			return 0, 0, 0, false
620		}
621		out := [3]int{}
